-- Phase 6: timetable and attendance
create table if not exists public.timetable_entries (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id) on delete cascade, class_id uuid not null references public.academic_classes(id) on delete cascade, section_id uuid references public.sections(id) on delete set null, subject_id uuid not null references public.subjects(id) on delete cascade, teacher_id uuid references public.staff(id) on delete set null, weekday smallint not null check (weekday between 1 and 7), period_no smallint not null check (period_no > 0), starts_at time, ends_at time, room text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(institution_id,class_id,section_id,weekday,period_no));
create table if not exists public.attendance_sessions (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id) on delete cascade, class_id uuid not null references public.academic_classes(id) on delete cascade, section_id uuid references public.sections(id) on delete set null, subject_id uuid references public.subjects(id) on delete set null, teacher_id uuid references public.staff(id) on delete set null, attendance_date date not null, period_no smallint, status text not null default 'open' check (status in ('open','submitted','locked')), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.attendance_records (id uuid primary key default gen_random_uuid(), institution_id uuid not null references public.institutions(id) on delete cascade, session_id uuid not null references public.attendance_sessions(id) on delete cascade, student_id uuid not null references public.students(id) on delete cascade, status text not null default 'present' check (status in ('present','absent','late','excused')), remarks text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists timetable_entries_class_day_idx on public.timetable_entries(class_id,weekday,period_no);
create index if not exists timetable_entries_teacher_idx on public.timetable_entries(teacher_id,weekday,period_no);
create index if not exists timetable_entries_institution_idx on public.timetable_entries(institution_id);
create index if not exists attendance_sessions_date_class_idx on public.attendance_sessions(attendance_date,class_id);
create index if not exists attendance_sessions_institution_idx on public.attendance_sessions(institution_id);
create index if not exists attendance_records_session_idx on public.attendance_records(session_id);
create index if not exists attendance_records_student_idx on public.attendance_records(student_id);
alter table public.timetable_entries enable row level security;
alter table public.attendance_sessions enable row level security;
alter table public.attendance_records enable row level security;
drop policy if exists timetable_select on public.timetable_entries;
drop policy if exists timetable_write on public.timetable_entries;
create policy timetable_select on public.timetable_entries for select using (app_private.is_super_admin() or (app_private.has_permission('academics.view') and institution_id=(select institution_id from public.profiles where id=(select auth.uid()))));
create policy timetable_write on public.timetable_entries for all using (app_private.is_super_admin() or (app_private.has_permission('academics.edit') and institution_id=(select institution_id from public.profiles where id=(select auth.uid())))) with check (app_private.is_super_admin() or (app_private.has_permission('academics.edit') and institution_id=(select institution_id from public.profiles where id=(select auth.uid()))));
drop policy if exists attendance_sessions_select on public.attendance_sessions;
drop policy if exists attendance_sessions_write on public.attendance_sessions;
create policy attendance_sessions_select on public.attendance_sessions for select using (app_private.is_super_admin() or (app_private.has_permission('attendance.view') and institution_id=(select institution_id from public.profiles where id=(select auth.uid()))));
create policy attendance_sessions_write on public.attendance_sessions for all using (app_private.is_super_admin() or (app_private.has_permission('attendance.create') and institution_id=(select institution_id from public.profiles where id=(select auth.uid())))) with check (app_private.is_super_admin() or (app_private.has_permission('attendance.create') and institution_id=(select institution_id from public.profiles where id=(select auth.uid()))));
drop policy if exists attendance_records_select on public.attendance_records;
drop policy if exists attendance_records_write on public.attendance_records;
create policy attendance_records_select on public.attendance_records for select using (app_private.is_super_admin() or (app_private.has_permission('attendance.view') and institution_id=(select institution_id from public.profiles where id=(select auth.uid()))));
create policy attendance_records_write on public.attendance_records for all using (app_private.is_super_admin() or (app_private.has_permission('attendance.create') and institution_id=(select institution_id from public.profiles where id=(select auth.uid())))) with check (app_private.is_super_admin() or (app_private.has_permission('attendance.create') and institution_id=(select institution_id from public.profiles where id=(select auth.uid()))));